<script setup lang="ts">
import { computed, ref } from 'vue'
import { ChevronRight, ChevronDown, Folder, Search } from '@lucide/vue'
import type { Category } from '../domain/catalog'
const props=defineProps<{categories:Category[];selected?:number|null;movable?:boolean}>();const emit=defineEmits<{select:[id:number];move:[id:number,ids:number[]]}>();const query=ref('');const collapsed=ref<number[]>([])
const rows=computed(()=>{const byId=new Map(props.categories.map(c=>[c.id,c]));const children=new Map<number,Category[]>();for(const c of props.categories){const p=c.parent&&byId.has(c.parent)?c.parent:0;children.set(p,[...(children.get(p)??[]),c])}const result:{category:Category;depth:number;hasChildren:boolean}[]=[];const visited=new Set<number>();const q=query.value.trim().toLowerCase();const matches=(c:Category,seen=new Set<number>()):boolean=>{if(seen.has(c.id))return false;seen.add(c.id);return c.name.toLowerCase().includes(q)||(children.get(c.id)??[]).some(child=>matches(child,seen))};const walk=(id:number,depth:number)=>{for(const c of children.get(id)??[]){if(visited.has(c.id))continue;visited.add(c.id);if(q&&!matches(c))continue;result.push({category:c,depth,hasChildren:!!children.get(c.id)?.length});if(q||!collapsed.value.includes(c.id))walk(c.id,depth+1)}};walk(0,0);return result})
function toggle(id:number){collapsed.value=collapsed.value.includes(id)?collapsed.value.filter(x=>x!==id):[...collapsed.value,id]}
function drop(event:DragEvent,id:number){if(!props.movable)return;try{const ids=JSON.parse(event.dataTransfer?.getData('application/x-ukm-products')??'[]');if(Array.isArray(ids)&&ids.length&&ids.every(Number.isInteger))emit('move',id,ids)}catch{/* Ignore unrelated browser drags. */}}
</script>
<template><section class="category-tree"><label class="search-field"><Search :size="16" /><input v-model="query" placeholder="Найти раздел" aria-label="Поиск категорий" /></label><p v-if="movable" class="field-hint">Перетащите товар в раздел для подготовки переноса.</p><div v-for="row in rows" :key="row.category.id" class="tree-row" :class="{active:selected===row.category.id}" :style="{paddingLeft:`${8+Math.min(row.depth,6)*16}px`}" @dragover.prevent @drop.prevent="drop($event,row.category.id)"><button v-if="row.hasChildren" class="icon-button" :aria-label="`Свернуть или раскрыть ${row.category.name}`" @click="toggle(row.category.id)"><ChevronRight v-if="collapsed.includes(row.category.id)" :size="14" /><ChevronDown v-else :size="14" /></button><span v-else class="tree-spacer" /><button class="tree-link" @click="emit('select',row.category.id)"><Folder :size="17" /><span>{{ row.category.name }}</span><small :title="'Товаров непосредственно в разделе'">{{ row.category.catalogCount }}</small></button></div><p v-if="!rows.length" class="muted">Разделы не найдены.</p></section></template>
